86	    36	INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-029', 'RP', 'P1', 'OPEN', NULL, NULL, 'THE GAP-018 PREDICTOR IS FALSIFIED, AND THE RESULT REPORTED AS ITS FIRST SUCCESS WAS A SCREEN ARTEFACT. THIS RETRACTS A CLAIM MADE EARLIER IN THIS SAME BATCH. The predictor: a paper cites the literature of its OWN INDEPENDENT VARIABLE, so what an anchor MEASURES predicts backward yield better than what it is ABOUT. TWO PRE-REGISTERED PREDICTIONS, BOTH FAILED, IN OPPOSITE DIRECTIONS. REF-00983, whose independent variable IS ramp slope, predicted >= 8 and returned 2 of 23 -- its references are the TRANSIT-VEHICLE and ADA-guidelines literature, because a reference list follows the papers FIELD and problem framing, not its independent variable. REF-00986, whose independent variable is activity type, predicted <= 4 and returned 9 of 45. Both failing in opposite directions on one test is the hypothesis being wrong, not noise. THEN THE SCREEN WAS TESTED AND IT IS CONFOUNDED, which is worse. The screen regex carries propuls and accessib, so ANY wheelchair-propulsion paper matches regardless of slope content. Under a STRICT slope-only screen (ramp|slope|incline|gradient|grade|cross-slope): REF-00986 falls 9 to 0 of 45; REF-00979 falls 19 TO 2 OF 30. REF-00979 IS THE 19-OF-30 THIS BATCH REPORTED AS THE PREDICTORS FIRST PASSED PROSPECTIVE TEST, in a commit message, a session record and a PR body. It was counting cites wheelchair-propulsion papers, which is trivially true of a wheelchair-propulsion paper. NOTE WHICH ANCHOR SURVIVES THE STRICT SCREEN BEST: REF-00980, 4 of 25, the one I predicted LOW -- its hits are genuinely ramp-titled. So the strict screen inverts the original ranking as well. WHAT IS NOW OWED: (1) GAP-018 and GAP-027 are superseded by this row; do not cite either as support. (2) Every yield figure this project has recorded for a mining pass used the loose screen and is an OVERCOUNT of slope relevance -- re-derive with the strict screen before quoting any of them. (3) If a predictor is wanted at all, the candidate the data now suggests is FIELD AND PROBLEM FRAMING rather than independent variable, and it must be pre-registered and tested the same way rather than adopted because it fits five retrospective points.', '2026-09-18 21:37', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:37', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
87	    37	INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-030', 'SW', 'P1', 'OPEN', NULL, NULL, 'GAP-008 HAS NOW BLOCKED THE SAME ADMISSION TWICE, AND THIS BATCH HAS THE CONCRETE PROOF OF THE CORRUPTION RATHER THAN THE PATTERN. Rouvier et al. 2022 (10.1371/journal.pone.0269657, PLOS ONE, open access, 76 references deposited) was retrieved and verified through Crossref this batch and COULD NOT BE ADMITTED. add-source refuses under R9 because the DOI is filed in source_locators as REF-00037 and R9 says cross-file rather than duplicate. REF-00037 IS CORRUPT IN A WAY THAT MAKES THAT INSTRUCTION DESTRUCTIVE: its doi column holds the PLOS ONE identifier while its title column reads Inclusive Housing Design Guide. RIBA/Habinteg/CAE. DOI:10.4324/9781003564164, authors Runnalls and Walker, year 2024 -- a different work, with a different DOI sitting inside the title text. REF-VERIFIED-003 holds the same DOI with title, authors and year all NULL. So R9, applied to a corrupt stash, directs an admission onto a mismatched identifier and would carry the corruption into evidence_sources. THIS IS THE SAME SHAPE THE 2026-09-16 RETIRE-IN-PLACE RULING RECORDS from batch 08, one row-state along: there, thirteen RETIRED tombstones were read as live DOI claims and the only remedy offered was to cross-file a retired identifier; it was fixed by exempting RETIRED rows. REFERENCE-ONLY rows whose DOI does not match their own title are the unfixed member of that class. WHAT IS MISSING AND WHY NOTHING WAS FORCED: update-locator writes status only; the vocabulary is REFERENCE-ONLY, PROMOTED, SCREENED-OUT, RETIRED, and none of them honestly states this row DOI does not belong to its title -- SCREENED-OUT asserts a lead was worked and judged unacceptable, which is false here, and would also bury a housing-guide lead whose own title and authors look sound. Hand SQL was not used (CLAUDE.md section 4). PROPOSED, NOT BUILT: a correct-locator that reads doi and title from a persisted retrieval payload and takes no value flag, the way correct-source does -- which is what source_locators_integrity has been asking for at advisory level while this defect blocks admissions at blocking level.', '2026-09-18 21:38', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:38', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
