90	    40	INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (75, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1080/17483107.2018.1465602 -- deposited reference list of REF-00983, screened for ramp/slope relevance (GAP-025 item 4, GAP-027 pre-registered floor)', NULL, 'crossref', 'systematic', 'backward', 23, 23, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:37', 'PREDICTION FAILED. Predicted >= 8; got 2 OF 23. The predictor said a paper cites the literature of its own independent variable, and ramp slope IS this paper independent variable -- yet its references are the TRANSIT-VEHICLE and ADA-guidelines literature, not the slope-biomechanics literature. The reason is visible once stated: a papers reference list follows its FIELD and its problem framing, not its independent variable. A transit-boarding study cites transit studies. That is a mechanism the predictor did not account for and it is fatal to the simple form of it.', 0, 'GAP-027 requires a floor recorded BEFORE the pass. REF-00983 independent variable IS ramp slope (propulsion on ramp slopes encountered when boarding public transit buses), so the GAP-018 predictor says HIGH YIELD: floor >= 8 of its references match the screen.');
91	    41	INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (76, 'accessible-circulation-geometry', NULL, 'EN', 1, 'clinical', 'high_control', 'https://api.crossref.org/works/10.1016/j.jelekin.2025.103027 -- deposited reference list of REF-00986, screened for ramp/slope relevance (GAP-025 item 4, GAP-027 pre-registered floor)', NULL, 'crossref', 'systematic', 'backward', 45, 45, 0, NULL, NULL, NULL, 0, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:37', 'PREDICTION FAILED IN THE OTHER DIRECTION, AND IT TRIGGERED THE CLAUSE THE PRIOR WROTE FOR EXACTLY THIS. Predicted <= 4; got 9 OF 45. Both predictions failing in OPPOSITE directions on the same test is not noise, it is the hypothesis being wrong. THEN THE SCREEN ITSELF WAS TESTED and it is confounded: the screen regex includes propuls and accessib, so ANY wheelchair-propulsion paper matches whether or not it concerns slope. Re-run with a STRICT slope-only screen (ramp|slope|incline|gradient|grade|cross-slope): REF-00986 falls 9 to 0 of 45, and REF-00979 -- the batch headline success -- falls 19 to 2 OF 30. THE FIRST HALF OF THIS BATCH REPORTED A PASSED PREDICTION THAT WAS A SCREEN ARTEFACT. Recorded in full at GAP-029.', 0, 'GAP-027 floor, recorded before the pass. REF-00986 independent variable is ACTIVITY TYPE, not slope -- its own extraction is graded absent because it states no incline. Predictor says LOW: I predict <= 4. THIS IS THE SHARPER TEST: both REF-00983 and REF-00986 are wheelchair biomechanics on the same slug and only the independent variable differs. If REF-00986 also comes back high, the predictor is measuring is it about wheelchairs rather than what does it measure, and GAP-027 must say so.');
