116	    66	INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (114, 75, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Manual wheelchair biomechanics while overcoming various environmental barriers: A systematic review (Rouvier et al., PLOS ONE, 2022)', '10.1371/journal.pone.0269657', 'UNVERIFIED', 2, 0, 'BLOCKED BY GAP-008, AND THE BLOCK IS A LIVE DEMONSTRATION OF IT. Retrieved and verified via Crossref (PLOS ONE, open access, 76 references deposited, full byline). add-source REFUSED it under R9: the DOI is already filed as REF-00037 in source_locators, and the instruction is to cross-file that ref_id. BUT REF-00037 IS CORRUPT -- it carries this PLOS ONE DOI while its own title reads Inclusive Housing Design Guide. RIBA/Habinteg/CAE. DOI:10.4324/9781003564164 by Runnalls and Walker 2024, a different work with a DIFFERENT DOI embedded in the title field. A second row, REF-VERIFIED-003, carries the same DOI with no title at all. Cross-filing would attach a systematic review of wheelchair biomechanics to an identifier whose stash row describes a housing design guide. NO REPAIR IS AVAILABLE THROUGH THE CLI: update-locator sets status only, and the status vocabulary (REFERENCE-ONLY/PROMOTED/SCREENED-OUT/RETIRED) contains nothing that honestly says this row DOI does not belong to its title. Not admitted, not forced, and not bypassed with hand SQL. This is the second time GAP-008 has blocked a real admission -- batch 15 hit it on Rouvier too.', NULL, 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:38');
