123	    73	INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (49, 'REF-01003', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'absent', NULL, NULL, 'Paths meeting the proposed accessibility guidelines were rated as either easy or moderate for difficulty of use.', 'abstract', NULL, 'measurement_primary', 'REF-01003', NULL, 'field_observation', 'not_device_scoped', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'A SECOND confirms EDGE AGAINST A STANDARD, after REF-00980 -- and it states no value, so it is graded absent. THE POPULATION IS THE PROBLEM AND IT WAS PREDICTED BEFORE RETRIEVAL: the 23 participants had vision OR mobility limitations and WALKED at their preferred pace, so they are AMBULATORY, not wheelchair users. Graded PROXY for MOB, and the authors say so themselves -- their closing line calls for future work to examine different perceptions between ambulatory individuals and wheelchair users. THE SECOND FINDING IS THE MORE INTERESTING ONE and is recorded here rather than as its own row because it carries no value either: slopes exceeding the guidelines may also be acceptable for very short distances or on hard-paved surfaces. That is DISTANCE-CONDITIONING measured in the field -- the same structure as REF-01002 20 ft bound and REF-00996 stated mechanism, now from a third method. T3 by the ratified ladder (clinical + lower_control, a pilot field study with no control condition), so it CANNOT lift parameter 3 off proxy, which the priors recorded before retrieval so the temptation to grade it up is on the record.', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 21:35', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', 'finding', NULL);
